{
  "name": "UP20超声探头",
  "name_en": "UP20 Ultrasound Probe",
  "manufacturer": "Interson",
  "description": "用于超声成像的USB探头设备，可通过USB控制传输与批量传输进行初始化、寄存器配置、图像采集、冻结/解冻、原始图像读取以及多普勒相关采集控制，适用于实验中的超声观察与数据获取。",
  "description_en": "A USB ultrasound probe used for ultrasound imaging. It is controlled through USB control and bulk transfers for initialization, register configuration, image acquisition, freeze/unfreeze operation, raw image retrieval, and Doppler-related acquisition, making it suitable for experimental ultrasound observation and data capture.",
  "tag_hints": [
    "ultrasound imaging",
    "USB probe",
    "Doppler ultrasound",
    "image acquisition",
    "bulk/control USB transfer",
    "probe initialization",
    "raw image capture"
  ],
  "actions": [
    {
      "action_name": "auto-BulkOut",
      "description": "通过USB批量输出向探头发送数据负载。",
      "description_en": "Send a data payload to the probe through USB bulk-out transfer."
    },
    {
      "action_name": "auto-BulkIn",
      "description": "通过USB批量输入从探头接收指定长度的数据。",
      "description_en": "Receive a specified amount of data from the probe through USB bulk-in transfer."
    },
    {
      "action_name": "auto-ControlIn",
      "description": "通过USB控制输入从设备读取控制响应。",
      "description_en": "Read a control response from the device through USB control-in transfer."
    },
    {
      "action_name": "auto-ControlOut",
      "description": "通过USB控制输出向设备发送控制请求与参数。",
      "description_en": "Send a control request and parameters to the device through USB control-out transfer."
    },
    {
      "action_name": "auto-InitOneA",
      "description": "发送两字节初始化命令以设置探头。",
      "description_en": "Send a two-byte initialization command to configure the probe."
    },
    {
      "action_name": "auto-Read512",
      "description": "从设备读取512字节数据块。",
      "description_en": "Read a 512-byte data block from the device."
    },
    {
      "action_name": "auto-BulkOutTwo",
      "description": "通过USB批量输出发送两字节数据。",
      "description_en": "Send a two-byte payload through USB bulk-out transfer."
    },
    {
      "action_name": "auto-BulkOutTwo512",
      "description": "发送与512字节读写流程相关的两字节批量命令。",
      "description_en": "Send a two-byte bulk command associated with a 512-byte transfer workflow."
    },
    {
      "action_name": "auto-BulkOutFour",
      "description": "通过USB批量输出发送四字节数据。",
      "description_en": "Send a four-byte payload through USB bulk-out transfer."
    },
    {
      "action_name": "auto-BulkOutLarge",
      "description": "分块向设备发送大容量数据。",
      "description_en": "Send a large payload to the device in chunks."
    },
    {
      "action_name": "auto-readWrite",
      "description": "写入命令并检查返回内容是否与预期一致。",
      "description_en": "Write a command and verify that the returned data matches the expected reply."
    },
    {
      "action_name": "auto-Init1004",
      "description": "发送四字节1004类初始化命令。",
      "description_en": "Send a four-byte 1004-type initialization command."
    },
    {
      "action_name": "auto-InitOn",
      "description": "执行设备上电或启用初始化流程。",
      "description_en": "Run the device power-on or enable initialization sequence."
    },
    {
      "action_name": "auto-InitSeries10",
      "description": "执行10系列初始化步骤。",
      "description_en": "Run the series-10 initialization sequence."
    },
    {
      "action_name": "auto-InitArrays",
      "description": "初始化探头内部数组参数。",
      "description_en": "Initialize internal array parameters of the probe."
    },
    {
      "action_name": "auto-InitRegisters",
      "description": "初始化设备寄存器与采集相关参数。",
      "description_en": "Initialize device registers and acquisition-related parameters."
    },
    {
      "action_name": "auto-freeze",
      "description": "冻结超声图像采集。",
      "description_en": "Freeze ultrasound image acquisition."
    },
    {
      "action_name": "auto-unfreeze",
      "description": "解除冻结并恢复超声图像采集。",
      "description_en": "Unfreeze the system and resume ultrasound image acquisition."
    },
    {
      "action_name": "auto-getImages",
      "description": "获取指定数量的超声图像。",
      "description_en": "Acquire the specified number of ultrasound images."
    },
    {
      "action_name": "auto-saveImage",
      "description": "保存指定编号的采集图像。",
      "description_en": "Save an acquired image by index."
    },
    {
      "action_name": "auto-DLImgs",
      "description": "下载一组超声图像。",
      "description_en": "Download a set of ultrasound images."
    },
    {
      "action_name": "auto-checkAddress",
      "description": "检查指定设备地址是否可访问或有效。",
      "description_en": "Check whether a specified device address is accessible or valid."
    },
    {
      "action_name": "auto-checkAddressFull",
      "description": "执行更完整的设备地址检查。",
      "description_en": "Perform a more complete check of a device address."
    },
    {
      "action_name": "auto-StartRun",
      "description": "启动一次设备运行或扫描流程。",
      "description_en": "Start a device run or scan sequence."
    },
    {
      "action_name": "auto-startMotor",
      "description": "启动探头相关电机机构。",
      "description_en": "Start the probe-related motor mechanism."
    },
    {
      "action_name": "auto-startAcq",
      "description": "开始数据或图像采集。",
      "description_en": "Start data or image acquisition."
    },
    {
      "action_name": "auto-stopMotor",
      "description": "停止探头相关电机机构。",
      "description_en": "Stop the probe-related motor mechanism."
    },
    {
      "action_name": "auto-stopAcq",
      "description": "停止数据或图像采集。",
      "description_en": "Stop data or image acquisition."
    },
    {
      "action_name": "auto-fastMotor",
      "description": "将电机切换到更快的运行方式。",
      "description_en": "Switch the motor to a faster operating mode."
    },
    {
      "action_name": "auto-getRawImages",
      "description": "获取原始超声图像数据。",
      "description_en": "Retrieve raw ultrasound image data."
    },
    {
      "action_name": "auto-getUSBImages",
      "description": "通过USB读取超声图像数据。",
      "description_en": "Read ultrasound image data over USB."
    },
    {
      "action_name": "auto-progIt",
      "description": "向设备写入或编程配置数据。",
      "description_en": "Program or write configuration data to the device."
    },
    {
      "action_name": "auto-createLoop",
      "description": "创建连续采集或扫描循环。",
      "description_en": "Create a continuous acquisition or scanning loop."
    },
    {
      "action_name": "auto-initProbe",
      "description": "初始化超声探头。",
      "description_en": "Initialize the ultrasound probe."
    },
    {
      "action_name": "auto-startDoppler",
      "description": "启动多普勒超声模式。",
      "description_en": "Start Doppler ultrasound mode."
    },
    {
      "action_name": "auto-getImagesDoppler",
      "description": "获取多普勒模式下的图像数据。",
      "description_en": "Acquire image data in Doppler mode."
    },
    {
      "action_name": "auto-createLoopDoppler",
      "description": "创建多普勒模式的连续采集循环。",
      "description_en": "Create a continuous acquisition loop for Doppler mode."
    }
  ]
}

